import {
  nextTestSetup,
  FileRef,
  isNextDev,
  isNextDeploy,
  patchFileWithDeployEnvAssignments,
} from 'e2e-utils'
import * as path from 'path'
import { realpathSync } from 'fs'

// A bundled CommonJS module from a workspace package (outside of the Next.js
// project directory) reads a sibling asset relative to `__dirname`, like the
// glue code generated by `wasm-bindgen --target nodejs`.
//
// webpack (`node.__dirname: 'eval-only'`) resolves `__dirname` to the
// directory of the output chunk instead, where the asset doesn't exist, so the
// fixture can't even build.
// @force-gate turbopack
describe('dirname-monorepo-package', () => {
  const { next } = nextTestSetup({
    files: {
      apps: new FileRef(path.resolve(__dirname, 'apps')),
      packages: new FileRef(path.resolve(__dirname, 'packages')),
      'vercel.json': new FileRef(path.resolve(__dirname, 'vercel.json')),
      'pnpm-workspace.yaml': `packages:
      - 'apps/*'
      - 'packages/*'
      `,
    },
    overrideFiles: {
      'apps/web/next.config.ts': patchFileWithDeployEnvAssignments(
        path.join(__dirname, 'apps/web/next.config.ts')
      ),
    },
    packageJson: require('./package.json'),
    buildCommand: 'pnpm build',
    startCommand: isNextDev ? 'pnpm dev' : 'pnpm start',
    installCommand: 'pnpm i',
  })

  it('should resolve __dirname and __filename to the real location of the module', async () => {
    const res = await next.fetch('/api/read-asset')
    const text = await res.text()
    expect({ status: res.status, text }).toMatchObject({ status: 200 })

    const data = JSON.parse(text)
    expect(data.wasmByteLength).toBe(8)

    if (isNextDeploy) {
      // The deployment's filesystem layout is not known to the test.
      expect(data.dirname).toMatch(/\/packages\/my-wasm-pkg\/wasm$/)
      expect(data.dirname).not.toMatch(/^\/ROOT\//)
    } else {
      const pkgDir = path.join(
        realpathSync(next.testDir),
        'packages/my-wasm-pkg/wasm'
      )
      expect(data).toEqual({
        dirname: pkgDir,
        filename: path.join(pkgDir, 'my_wasm.js'),
        wasmPath: path.join(pkgDir, 'my_wasm_bg.wasm'),
        wasmByteLength: 8,
      })
    }
  })
})
